// Procesar CSV manualmente
const csvText = items[0].json.data;
const lines = csvText.split('\n');
const products = [];

for (let i = 0; i < lines.length; i++) {
  const line = lines[i].trim();
  if (!line) continue; // Saltar líneas vacías

  // Split por punto y coma, ignorando comillas
  const fields = line.split(';');

  // Limpiar comillas de todos los campos
  const cleanFields = fields.map(field => field.replace(/"/g, '').trim());

  // Mapear a objeto
  products.push({
    json: {
      proveedor: 'jim_sports',
      ref_proveedor: cleanFields[0] || null,
      ref_variante: cleanFields[1] || null,
      ean: cleanFields[2] || null,
      stock: parseInt(cleanFields[3]) || 0,
      name: cleanFields[4] || '',
      marca: cleanFields[5] || null,
      imagen: cleanFields[6] || null,
      categoria: cleanFields[7] || null,
      categoria_padre: cleanFields[8] || null,
      color: cleanFields[9] || null,
      talla: cleanFields[10] || null,
      slug: (cleanFields[4] || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') + '-' + (cleanFields[0] || ''),
      published: true,
      activo: true,
      visible_web: true
    }
  });
}

return products;
